class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, j):
            if i > j:
                return 0
            res = 0
            for c in 'abcd':
                try:
                    l = s.index(c, i, j + 1)
                except ValueError:
                    continue
                r = s.rindex(c, i, j + 1)
                if l == r:
                    res += 1
                else:
                    res += 2 + dp(l + 1, r - 1)
            return res % MOD

        return dp(0, n - 1)

