class Solution {
public:
    int countPalindromicSubsequences(string s) {
        const int MOD = 1e9 + 7;
        int n = s.size();
        vector<vector<int>> memo(n, vector<int>(n, -1));
        function<int(int,int)> dp = [&](int i, int j) -> int {
            if (i > j) return 0;
            if (memo[i][j] != -1) return memo[i][j];
            long long res = 0;
            for (char c = 'a'; c <= 'd'; ++c) {
                int l = -1, r = -1;
                for (int k = i; k <= j; ++k) if (s[k] == c) { if (l == -1) l = k; r = k; }
                if (l == -1) continue;
                if (l == r) res += 1;
                else res += 2 + dp(l + 1, r - 1);
            }
            return memo[i][j] = res % MOD;
        };
        return dp(0, n - 1);
    }
};

