class Solution {
    private Integer[][] memo;
    private String s;
    private final int MOD = 1_000_000_007;

    public int countPalindromicSubsequences(String s) {
        this.s = s;
        int n = s.length();
        memo = new Integer[n][n];
        return dp(0, n - 1);
    }

    private int dp(int i, int j) {
        if (i > j) return 0;
        if (memo[i][j] != null) return memo[i][j];
        long res = 0;
        for (char c = 'a'; c <= 'd'; c++) {
            int l = -1, r = -1;
            for (int k = i; k <= j; k++) {
                if (s.charAt(k) == c) { if (l == -1) l = k; r = k; }
            }
            if (l == -1) continue;
            if (l == r) res += 1;
            else res += 2 + dp(l + 1, r - 1);
        }
        return memo[i][j] = (int)(res % MOD);
    }
}

