class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                res = 0
                for c in range(4):
                    ch = chr(ord('a') + c)
                    l = r = -1
                    lo, hi = i, j
                    while lo <= hi:
                        if s[lo] != ch: lo += 1
                        elif s[hi] != ch: hi -= 1
                        else: break
                    if lo > hi:
                        continue
                    l, r = lo, hi
                    if l == r:
                        res += 1
                    else:
                        res += 2 + dp[l + 1][r - 1]
                dp[i][j] = res % MOD
        return dp[0][n - 1]

