class Solution {
public:
    int countPalindromicSubsequences(string s) {
        const long long MOD = 1e9 + 7;
        int n = s.size();
        vector<vector<long long>> dp(n, vector<long long>(n, 0));
        for (int i = 0; i < n; ++i) dp[i][i] = 1;
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len - 1 < n; ++i) {
                int j = i + len - 1;
                long long res = 0;
                for (char c = 'a'; c <= 'd'; ++c) {
                    int lo = i, hi = j;
                    while (lo <= hi && !(s[lo] == c && s[hi] == c)) {
                        if (s[lo] != c) ++lo;
                        if (lo <= hi && s[hi] != c) --hi;
                    }
                    if (lo > hi) continue;
                    if (lo == hi) res += 1;
                    else res += 2 + dp[lo + 1][hi - 1];
                }
                dp[i][j] = res % MOD;
            }
        }
        return (int)dp[0][n - 1];
    }
};

